pub const API_VERSION: u32 = 0x01020304;

// feature flags
pub const FEAT_A: i32 = 1 << 0;
/// the b feature
pub const FEAT_B: i32 = 1 << 3;
pub const FEAT_AB: i32 = FEAT_A | FEAT_B;
pub const FEAT_LIT: i32 = FEAT_A | 4;

pub const FEAT_ONE: u32 = 1 << 0;
pub const FEAT_ALL: u32 = FEAT_ONE | 8;

// access flags
pub const ACC_A: i32 = 1 << 0;
pub const ACC_B: i32 = 1 << 1;
pub const ACC_AB: i32 = ACC_A | ACC_B;

pub fn access_to_string(mut value: i32) -> String {
    if value == 0 {
        return String::from("NONE");
    }
    let mut text = String::new();
    if value & ACC_A != 0 {
        text += "|ACC_A";
        value &= !ACC_A;
    }
    if value & ACC_B != 0 {
        text += "|ACC_B";
        value &= !ACC_B;
    }
    if value != 0 {
        text += &format!("|{value:#x}");
    }
    text[1..].to_string()
}

