impl Text {
    /// The bytes of `arena` this run covers; `None` where the run leaves `arena`.
    pub fn resolve<'a>(&self, arena: &'a [u8]) -> Option<&'a [u8]> {
        let (offset, length) = (self.offset as usize, self.length as usize);
        arena.get(offset..offset.checked_add(length)?)
    }
}

/// Why a walk of a union's list refused it, beside the record's index and byte offset in a
