/// a port
pub struct Port {
    handle: ffi::xy_port,
    _in_call: core::cell::Cell<Option<&'static str>>,
    pstats: Stats,
    generation: u32,
    pwrap: Wrap,
}

impl Port {
    pub fn create(unit: u32) -> Result<Port, Status> {
        let mut pport = core::ptr::null_mut();
        let mut pstats = Stats::default();
        let mut generation = u32::default();
        let mut pwrap = Wrap::default();
        // SAFETY: every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe {
            ffi::xy_open_port(unit, &mut pport, &mut pstats, &mut generation, &mut pwrap)
        };
        let result =
            Status::try_from(raw).expect("xy_open_port returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        Ok(Port {
            handle: pport,
            _in_call: core::cell::Cell::new(None),
            pstats,
            generation,
            pwrap,
        })
    }

    pub fn handle(&self) -> ffi::xy_port {
        self.handle
    }

    pub fn pstats(&self) -> &Stats {
        &self.pstats
    }

    pub fn generation(&self) -> u32 {
        self.generation
    }

    pub fn pwrap(&self) -> &Wrap {
        &self.pwrap
    }

    /// buf: bytes to send
    pub fn send(&self, buf: &[u8]) -> Result<(), Status> {
        if self._in_call.get().is_some() {
            return Err(Status::ErrBusy);
        }
        let buf_count = u64::try_from(buf.len()).expect("buf is longer than u64 can count");
        // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe { ffi::xy_send(self.handle, buf.as_ptr().cast(), buf_count) };
        let result =
            Status::try_from(raw).expect("xy_send returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        Ok(())
    }

    pub fn recv(&self, pdst: &mut [u8]) -> Result<(), Status> {
        if self._in_call.get().is_some() {
            return Err(Status::ErrBusy);
        }
        let pdst_count = u32::try_from(pdst.len()).expect("pdst is longer than u32 can count");
        // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe { ffi::xy_recv(self.handle, pdst.as_mut_ptr().cast(), pdst_count) };
        let result =
            Status::try_from(raw).expect("xy_recv returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        Ok(())
    }

    /// # Safety
    ///
    /// `who` must be a handle the library issued and has not yet destroyed.
    pub unsafe fn configure(
        &self,
        cfg: &Stats,
        limit: &u32,
        mode: Mode,
        who: ffi::xy_token,
    ) -> Result<(), Status> {
        if self._in_call.get().is_some() {
            return Err(Status::ErrBusy);
        }
        // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe { ffi::xy_configure(self.handle, cfg, limit, mode as ffi::xy_mode, who) };
        let result =
            Status::try_from(raw).expect("xy_configure returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        Ok(())
    }

    pub fn stats_of(&self) -> Result<(Stats, u32, ffi::xy_link), Status> {
        if self._in_call.get().is_some() {
            return Err(Status::ErrBusy);
        }
        let mut out = Stats::default();
        let mut pcount = u32::default();
        let mut plink = core::ptr::null_mut();
        // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe { ffi::xy_stats_of(self.handle, &mut out, &mut pcount, &mut plink) };
        let result =
            Status::try_from(raw).expect("xy_stats_of returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        Ok((out, pcount, plink))
    }

    /// level + 1, tally.count * 2, each byte of data + 1
    pub fn bump(&self, level: &mut u32, tally: &mut Stats, data: &mut [u8]) -> Result<(), Status> {
        if self._in_call.get().is_some() {
            return Err(Status::ErrBusy);
        }
        let data_count = u32::try_from(data.len()).expect("data is longer than u32 can count");
        // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe {
            ffi::xy_bump(
                self.handle,
                level,
                tally,
                data.as_mut_ptr().cast(),
                data_count,
            )
        };
        let result =
            Status::try_from(raw).expect("xy_bump returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        Ok(())
    }

    /// ok iff note is absent or note.count == 7
    pub fn annotate(&self, note: Option<&Stats>) -> Result<(), Status> {
        if self._in_call.get().is_some() {
            return Err(Status::ErrBusy);
        }
        // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe {
            ffi::xy_annotate(
                self.handle,
                note.map_or(core::ptr::null(), core::ptr::from_ref),
            )
        };
        let result =
            Status::try_from(raw).expect("xy_annotate returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        Ok(())
    }

    /// ok for 1 << 40; ok for 98 where the last batch-98 stream received an answer other than go, else err_again; for 96 during a batch-95 or batch-96 stream, calls that stream's sink once with empty views and answers ok; for 95, ok where the last batch-95 stream's first call was answered other than go, else err_again (the C++ fake only)
    pub fn seek(&self, offset: u64) -> Result<(), Status> {
        if self._in_call.get().is_some() {
            return Err(Status::ErrBusy);
        }
        // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe { ffi::xy_seek(self.handle, offset) };
        let result =
            Status::try_from(raw).expect("xy_seek returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        Ok(())
    }

    /// pnext = big - 1, pdelta = delta - 1; ok iff delta == -3, big == -(1 << 40), small == 200, scale == 0.5
    pub fn tune(&self, delta: i32, big: i64, small: u8, scale: f64) -> Result<(i64, i32), Status> {
        if self._in_call.get().is_some() {
            return Err(Status::ErrBusy);
        }
        let mut pnext = i64::default();
        let mut pdelta = i32::default();
        // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe {
            ffi::xy_tune(
                self.handle,
                delta,
                big,
                small,
                scale,
                &mut pnext,
                &mut pdelta,
            )
        };
        let result =
            Status::try_from(raw).expect("xy_tune returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        Ok((pnext, pdelta))
    }

    /// pmode = slow, level + 1 and ppeek = 9 where given; ok iff payload is absent or 2 bytes and limit is absent or 3
    pub fn probe(
        &self,
        payload: Option<&[u8]>,
        limit: Option<&u32>,
        level: Option<&mut u32>,
        ppeek: Option<&mut u32>,
    ) -> Result<Mode, Status> {
        if self._in_call.get().is_some() {
            return Err(Status::ErrBusy);
        }
        let mut pmode = ffi::xy_mode::default();
        let payload_count = u32::try_from(payload.map_or(0, <[u8]>::len))
            .expect("payload is longer than u32 can count");
        // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe {
            ffi::xy_probe(
                self.handle,
                &mut pmode,
                payload.map_or(core::ptr::null(), <[u8]>::as_ptr).cast(),
                payload_count,
                limit.map_or(core::ptr::null(), core::ptr::from_ref),
                level.map_or(core::ptr::null_mut(), core::ptr::from_mut),
                ppeek.map_or(core::ptr::null_mut(), core::ptr::from_mut),
            )
        };
        let result =
            Status::try_from(raw).expect("xy_probe returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        let pmode =
            Mode::try_from(pmode).expect("xy_probe wrote a pmode value xy_mode does not name");
        Ok(pmode)
    }

    /// ppos = pos
    pub fn echo_offset(&self, pos: Offset) -> Result<Offset, Status> {
        if self._in_call.get().is_some() {
            return Err(Status::ErrBusy);
        }
        let mut ppos = Offset::default();
        // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe { ffi::xy_echo_offset(self.handle, pos, &mut ppos) };
        let result =
            Status::try_from(raw).expect("xy_echo_offset returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        Ok(ppos)
    }

    /// entries e0..e2 (id 10 + i, label 'e<i>' at 2i) and their labels' arena 'e0e1e2', each as much as its buffer holds; lies at items capacity 4 (wrote 5, needed 9) and 6 (wrote 4), and at labels capacity 5 (wrote 7)
    pub fn list(&self, items: &mut [Entry], labels: &mut [u8]) -> Result<(Filled, Filled), Status> {
        if self._in_call.get().is_some() {
            return Err(Status::ErrBusy);
        }
        let items_count = u64::try_from(items.len()).expect("items is longer than u64 can count");
        let mut items_wrote = u64::default();
        let mut items_needed = u64::default();
        let labels_count =
            u32::try_from(labels.len()).expect("labels is longer than u32 can count");
        let mut labels_wrote = u32::default();
        let mut labels_needed = u32::default();
        // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe {
            ffi::xy_list(
                self.handle,
                items.as_mut_ptr(),
                items_count,
                &mut items_wrote,
                &mut items_needed,
                labels.as_mut_ptr().cast(),
                labels_count,
                &mut labels_wrote,
                &mut labels_needed,
            )
        };
        let result =
            Status::try_from(raw).expect("xy_list returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        assert!(
            items_wrote <= items_count && items_wrote <= items_needed,
            "xy_list over-reported items: it wrote more than the buffer holds or than the result needs"
        );
        assert!(
            labels_wrote <= labels_count && labels_wrote <= labels_needed,
            "xy_list over-reported labels: it wrote more than the buffer holds or than the result needs"
        );
        Ok((
            Filled {
                wrote: usize::try_from(items_wrote)
                    .expect("xy_list reported a size of items usize cannot hold"),
                needed: usize::try_from(items_needed)
                    .expect("xy_list reported a size of items usize cannot hold"),
            },
            Filled {
                wrote: usize::try_from(labels_wrote)
                    .expect("xy_list reported a size of labels usize cannot hold"),
                needed: usize::try_from(labels_needed)
                    .expect("xy_list reported a size of labels usize cannot hold"),
            },
        ))
    }

    /// entries e0..e6 (id 10 + i, label 'e<i>' at 2i) to sink: a batch when it holds batch entries (0: never) or a cut ends it, then a final call with the remainder, possibly empty; a sink answer other than go stops it with err_again; batch 99 calls sink from another thread (the C++ fake only); batch 98 delivers batches of 1 whatever the sink answers, err_again where any answer was not go; batch 97 (the C++ fake only) passes a null fresh with a count of 1 on its first call; batch 96 (the C++ fake only) lets seek(96) on any port call the sink again while it runs; batch 95 (the C++ fake only) lets seek(96) call the sink again as batch 96 does and delivers batches of 1 whatever the sink answers, err_again where any answer was not go
    pub fn stream(
        &self,
        batch: u32,
        cuts: &[Cut],
        sink: impl FnMut(&[Entry], &[Entry], &[u8], u32) -> Flow,
    ) -> Result<(), Status> {
        if self._in_call.get().is_some() {
            return Err(Status::ErrBusy);
        }
        let cuts_count = u32::try_from(cuts.len()).expect("cuts is longer than u32 can count");
        let _failure = CallbackFailure::default();
        let mut sink = CallbackFrame {
            callback: sink,
            thread: std::thread::current().id(),
            function: "xy_stream",
            running: core::cell::Cell::new(false),
            failure: &_failure,
        };
        self._in_call.set(Some("xy_stream"));
        // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe {
            ffi::xy_stream(
                self.handle,
                batch,
                cuts.as_ptr().cast::<ffi::xy_cut>(),
                cuts_count,
                self::on_batch_trampoline(&sink),
                core::ptr::from_mut(&mut sink).cast(),
            )
        };
        self._in_call.set(None);
        if let Some(panic) = _failure.panic.take() {
            std::panic::resume_unwind(panic);
        }
        let result =
            Status::try_from(raw).expect("xy_stream returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        Ok(())
    }

    /// calls first with sent as the mode, then second, whatever either answers; err_again where either answered other than go
    pub fn notify(
        &self,
        sent: u32,
        first: impl FnMut(Mode) -> Flow,
        second: impl FnMut(Mode) -> Flow,
    ) -> Result<(), Status> {
        if self._in_call.get().is_some() {
            return Err(Status::ErrBusy);
        }
        let _failure = CallbackFailure::default();
        let mut first = CallbackFrame {
            callback: first,
            thread: std::thread::current().id(),
            function: "xy_notify",
            running: core::cell::Cell::new(false),
            failure: &_failure,
        };
        let mut second = CallbackFrame {
            callback: second,
            thread: std::thread::current().id(),
            function: "xy_notify",
            running: core::cell::Cell::new(false),
            failure: &_failure,
        };
        self._in_call.set(Some("xy_notify"));
        // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe {
            ffi::xy_notify(
                self.handle,
                sent,
                self::on_mode_trampoline(&first),
                core::ptr::from_mut(&mut first).cast(),
                self::on_mode_trampoline(&second),
                core::ptr::from_mut(&mut second).cast(),
            )
        };
        self._in_call.set(None);
        if let Some(panic) = _failure.panic.take() {
            std::panic::resume_unwind(panic);
        }
        let result =
            Status::try_from(raw).expect("xy_notify returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        Ok(())
    }

    /// notes n0..n5 to sink, batch of them a call (0: all six in one), the last call holding the remainder; a sink answer other than go stops it with err_again; a batch above 6 is err_unsupported
    pub fn stream_notes(
        &self,
        batch: u32,
        sink: impl FnMut(NoteSequence<'_>, NoteSequence<'_>) -> Flow,
    ) -> Result<(), Status> {
        if self._in_call.get().is_some() {
            return Err(Status::ErrBusy);
        }
        let _failure = CallbackFailure::default();
        let mut sink = CallbackFrame {
            callback: sink,
            thread: std::thread::current().id(),
            function: "xy_stream_notes",
            running: core::cell::Cell::new(false),
            failure: &_failure,
        };
        self._in_call.set(Some("xy_stream_notes"));
        // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe {
            ffi::xy_stream_notes(
                self.handle,
                batch,
                self::on_notes_trampoline(&sink),
                core::ptr::from_mut(&mut sink).cast(),
            )
        };
        self._in_call.set(None);
        if let Some(panic) = _failure.panic.take() {
            std::panic::resume_unwind(panic);
        }
        let result = Status::try_from(raw)
            .expect("xy_stream_notes returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        Ok(())
    }

    /// release the port
    pub fn release(self) -> Result<(), Status> {
        let handle = self.handle;
        core::mem::forget(self);
        // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe { ffi::xy_destroy_port(handle) };
        let result = Status::try_from(raw)
            .expect("xy_destroy_port returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        Ok(())
    }
}

impl Drop for Port {
    fn drop(&mut self) {
        if !self.handle.is_null() {
            // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
            let _ = unsafe { ffi::xy_destroy_port(self.handle) };
        }
    }
}

/// `_in_call` is cleared before any panic is resumed, and a panic that escapes with it set
/// leaves the object refusing every method: poisoned, never unsound.
impl std::panic::RefUnwindSafe for Port {}

pub struct DataLink {
    handle: ffi::xy_link,
}

impl DataLink {
    pub fn create() -> Result<DataLink, Status> {
        let mut plink = core::ptr::null_mut();
        // SAFETY: every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe { ffi::xy_open_link(&mut plink) };
        let result =
            Status::try_from(raw).expect("xy_open_link returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        Ok(DataLink { handle: plink })
    }

    pub fn handle(&self) -> ffi::xy_link {
        self.handle
    }

    /// ok for a non-null link and port, else err_other
    pub fn attach(&self, hport: &Port) -> Result<(), Status> {
        if hport._in_call.get().is_some() {
            return Err(Status::ErrBusy);
        }
        // SAFETY: the handle came from a successful create and is not yet released; every pointer argument points at a local or a caller reference that lives for the call, a slice's length its count; the library keeps no pointer after returning.
        let raw = unsafe { ffi::xy_attach(self.handle, hport.handle) };
        let result =
            Status::try_from(raw).expect("xy_attach returned a value xy_status does not name");
        if result != Status::Ok {
            return Err(result);
        }
        Ok(())
    }
}
